CREATE TABLE IF NOT EXISTS `admin_user` (`admin` TINYINT(1) NOT NULL DEFAULT 0, `bootstrap_key` VARCHAR(32) NULL, `created_at` BIGINT NOT NULL, `id` BIGINT NOT NULL AUTO_INCREMENT, `name` VARCHAR(50) NOT NULL, `position` VARCHAR(50) NULL, `status` ENUM('active', 'disabled') NOT NULL DEFAULT 'active', `updated_at` BIGINT NOT NULL, `user_user` BIGINT NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_admin_user_user_user` (`user_user`), UNIQUE KEY `uk_admin_user_bootstrap_key` (`bootstrap_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
